#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Ticket 173's closing run: M8's exit from ticket 17, every checklist item
# (docs/testing/checklist.md) tagged M8, and every earlier one still open, on the installed
# packages. The items aren't copied here: the wizard reads them from the checklist, one stage
# for each, so it shows the checklist as it is in this checkout. It has five parts:
#
#   173-closing-checks.sh packages         on the host desktop: tools/check, then the packages
#   173-closing-checks.sh items M8         in MATE on Caminito: the items tagged M8, then
#                                          144's check and the decisions left to confirm
#   173-closing-checks.sh items M6 M7      in MATE on Caminito: the earlier items still open
#   173-closing-checks.sh x11              in X11 MATE, and then in MATE on Wayfire
#   173-closing-checks.sh message          anywhere: the results, as the closing commit has them
#
# Run them from the checkout, in a terminal you can still see while a check runs: over ssh
# from another machine is best for the items that lock, blank or end the session. Each
# result is saved as it's given, so a part that's stopped is run again and resumes. A part's
# last stage appends its results to 173-closing-results.md, beside the ticket.

PART="${1:-}"
shift || true
HERE="$(dirname "$(realpath "$0")")"
ROOT="$(realpath "$HERE/../..")"
CHECKLIST="$ROOT/docs/testing/checklist.md"
RESULTS_FILE="${RESULTS_FILE:-$HERE/173-closing-results.md}"
STATE="${XDG_STATE_HOME:-$HOME/.local/state}/caminito"
GATE="X11 MATE and the Wayfire session are unchanged with the Patched packages"
PARITY="The parity table's rows that no test covers"
# In tools/bootstrap's order: each is installed as it's built, so the next builds against it.
PACKAGES=(mate-session-manager-caminito mate-panel-caminito mate-settings-daemon-caminito
  mate-control-center-caminito caja-caminito mate-utils-caminito mate-power-manager-caminito
  caminito-git)
RESULTS=()   # "short name|pass, FAIL or not run|note"
FAILED=()
ITEMS=()     # the titles of the checklist items a part runs

usage() {
  sed -n '/^# Ticket 173/,/^$/p' "$0" | sed 's/^# \{0,1\}//'
  exit 2
}

# items_tagged M... prints the title of each checklist item whose Milestone line starts with
# one of the tags, in the checklist's order.
items_tagged() {
  local tags; tags=$(IFS='|'; printf '%s' "$*")
  awk -v tags="^- [*][*]Milestone:[*][*] ($tags)([^0-9]|$)" '
    /^### / { title = substr($0, 5); next }
    title != "" && $0 ~ tags { print title }
    /^- [*][*]Milestone:[*][*]/ { title = "" }
  ' "$CHECKLIST"
}
# item TITLE prints a checklist item: what's under its heading, up to the next one.
item() {
  awk -v title="### $1" '
    $0 == title { on = 1; next }
    on && /^##/ { exit }
    on { print }
  ' "$CHECKLIST" | sed -e '/./,$!d' -e 's/^/  /'
}

case $PART in
  packages) TOTAL_STAGES=4; WHERE="tools/check and the packages"; NAME=packages ;;
  items)
    (( $# )) || usage
    WHERE="the items tagged $*"; NAME="items-$(IFS=-; printf '%s' "$*")"
    mapfile -t ITEMS < <(items_tagged "$@" | grep -vxF -e "$GATE" -e "$PARITY" || true)
    (( ${#ITEMS[@]} )) || { echo "no checklist item is tagged $*" >&2; exit 2; }
    TOTAL_STAGES=$(( ${#ITEMS[@]} + 2 ))
    # M8's part ends with 144's check, the decisions and the pass over the parity table.
    [[ " $* " == *" M8 "* ]] && TOTAL_STAGES=$(( TOTAL_STAGES + 3 )) ;;
  x11) TOTAL_STAGES=3; WHERE="X11 MATE and MATE on Wayfire"; NAME=x11 ;;
  message) ;;
  *) usage ;;
esac
PROGRESS="$STATE/173-closing-checks-${NAME:-}.progress"

# show CMD... runs a command and shows it with its output, indented.
show() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@" 2>&1 | sed 's/^/    /' || true; }
# ok "..." prints a check that passed.
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
# installed prints the versions of the packages the run is on.
installed() { pacman -Q "${PACKAGES[@]}" zenity libcanberra marco 2>&1 | paste -sd, | sed 's/,/, /g'; }

# record NAME VERDICT NOTE saves a result as it's given.
record() {
  RESULTS+=("$1|$2|$3")
  printf '%s|%s|%s\n' "$1" "$2" "$3" >> "$PROGRESS"
  if [[ $2 == FAIL ]]; then FAILED+=("$1"); fi
}
# result "Short name" records whether the check passed, failed or wasn't run, with an
# optional note.
result() {
  local name="$1" reply="" verdict note=""
  printf '  %s? Did all of it work? (%s) [y]es, [n]o, [s]kipped:%s ' "$YELLOW" "$name" "$RESET"
  read -r reply || true
  case $reply in
    [Yy]*) verdict=pass ;;
    [Ss]*) verdict="not run" ;;
    *) verdict=FAIL ;;
  esac
  printf '  %sNote (what you saw; Enter for none):%s ' "$BOLD" "$RESET"
  read -r note || true
  # The results are kept one to a line, with | between their parts.
  record "$name" "$verdict" "${note//|//}"
}
# load_progress offers to resume from the results a stopped run saved.
load_progress() {
  local r name verdict note
  mkdir -p "$STATE"
  [[ -s $PROGRESS ]] || { rm -f "$PROGRESS"; return 0; }
  say "A stopped run saved these results:"
  while IFS= read -r r; do
    IFS='|' read -r name verdict note <<< "$r"
    say "  $verdict  $name${note:+ ($note)}"
  done < "$PROGRESS"
  if confirm "Resume, skipping the stages they cover? (No starts over)"; then
    mapfile -t RESULTS < "$PROGRESS"
    for r in "${RESULTS[@]}"; do
      IFS='|' read -r name verdict _ <<< "$r"
      if [[ $verdict == FAIL ]]; then FAILED+=("$name"); fi
    done
  else
    rm -f "$PROGRESS"
  fi
}
# done_already NAME succeeds, and says so, when NAME's result is recorded.
done_already() {
  local r
  for r in ${RESULTS[@]+"${RESULTS[@]}"}; do
    if [[ $r == "$1|"* ]]; then say "Already recorded; skipping."; sleep 1; return 0; fi
  done
  return 1
}
# checklist_stage TITLE is one checklist item: its text, then its result.
checklist_stage() {
  stage "Checklist: $1"
  done_already "$1" && return 0
  item "$1"
  printf '\n'
  result "$1"
}
# in_caminito warns when the terminal isn't in MATE on Caminito.
in_caminito() {
  if [[ $(systemctl --user show-environment 2>/dev/null | grep -c '^MATE_WM_NAME=Caminito$' || true) -gt 0 ]]; then
    ok "MATE on Caminito runs: MATE_WM_NAME=Caminito is in systemd's environment"
    show sh -c "readlink /proc/\$(pgrep -n -x -u $(id -u) caminito)/exe"
    note "Expected: /usr/bin/caminito, the installed package's."
  else
    warn "MATE on Caminito isn't running for $(id -un): log into it at the greeter first"
  fi
}
# record_stage is each part's last stage: it shows the results and writes them down.
record_stage() {
  local r name verdict note
  stage "Record the results"
  for r in ${RESULTS[@]+"${RESULTS[@]}"}; do
    IFS='|' read -r name verdict note <<< "$r"
    say "$verdict  $name${note:+ ($note)}"
  done
  if confirm "Write these down?"; then
    {
      printf '\n## %s (%s), as %s on %s\n\nOn %s.\n\n' \
        "${WHERE^}" "$(date +%F)" "$(id -un)" "$(uname -n)" "$(installed)"
      for r in ${RESULTS[@]+"${RESULTS[@]}"}; do
        IFS='|' read -r name verdict note <<< "$r"
        printf -- '- %s: %s.%s\n' "$name" "$verdict" "${note:+ $note}"
      done
    } >> "$RESULTS_FILE"
    printf '  %s✓ wrote%s %s results to %s\n' "$GREEN" "$RESET" "${#RESULTS[@]}" "$RESULTS_FILE"
    rm -f "$PROGRESS"
    (( ${#FAILED[@]} )) && SKIPPED+=("a new ticket for each failure, or its item's tag moved with a reason, before M8 closes: ${FAILED[*]}")
  else
    SKIPPED+=("recording the results (they stay in $PROGRESS)")
  fi
  SKIPPED+=("this wizard's other parts, unless 173-closing-results.md has them:  packages, items M8, items M6 M7, x11")
  SKIPPED+=("then:  173-closing-checks.sh message  for the Close M8 Marco parity commit")
  finish
}

if [[ $PART == message ]]; then
  [[ -s $RESULTS_FILE ]] || { echo "$RESULTS_FILE has no results yet" >&2; exit 1; }
  printf 'Close M8 Marco parity\n\n'
  printf 'Every org.mate.Marco.* key and all 103 actions are honoured, never\n'
  printf 'implemented, or on the roadmap: docs/parity.md has no row left to do.\n'
  printf 'Checklist (docs/testing/checklist.md), on the installed packages:\n'
  sed -e 's/^## /\n/' "$RESULTS_FILE" | fold -s -w 72
  exit 0
fi

banner "Ticket 173: M8's closing run, $WHERE"
load_progress

case $PART in
# ══ packages ══════════════════════════════════════════════════════════════
packages)

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "tools/check"
if ! done_already "tools/check"; then
  say "Run on the host desktop, from the checkout. It takes a while."
  show git -C "$ROOT" log --oneline -1
  if [[ -n $(git -C "$ROOT" status --porcelain) ]]; then
    warn "the checkout has uncommitted work: caminito-git packages the committed HEAD only"
  fi
  if confirm "Run tools/check now?"; then
    if (cd "$ROOT" && tools/check); then
      ok "tools/check passed"
      record "tools/check" pass "On $(git -C "$ROOT" rev-parse --short=7 HEAD)."
    else
      warn "tools/check failed"
      record "tools/check" FAIL "On $(git -C "$ROOT" rev-parse --short=7 HEAD)."
    fi
    pause
  else
    result "tools/check"
  fi
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Build and install the packages"
if ! done_already "The packages are installed from the built files"; then
  say "What's installed now:"
  show pacman -Q "${PACKAGES[@]}"
  say "The tree has:"
  for package in "${PACKAGES[@]}"; do
    say "  $package $(sed -n 's/^pkgver=//p' "$ROOT/packaging/arch/$package/PKGBUILD")-$(sed -n 's/^pkgrel=//p' "$ROOT/packaging/arch/$package/PKGBUILD")"
  done
  note "caminito-git's pkgver is the commit it's built from, which makepkg writes. A Patched"
  note "package whose pkgrel is the installed one has no new patch, and needn't be built again."
  for package in "${PACKAGES[@]}"; do
    if confirm "Build and install $package?"; then
      (cd "$ROOT/packaging/arch/$package" && makepkg -si) || warn "$package didn't build or install"
    fi
  done
  note "makepkg rewrote pkgver= in caminito-git's PKGBUILD: that change goes in the closing commit."
  result "The packages are installed from the built files"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "What the run is on"
if ! done_already "caminito-git brings zenity and libcanberra"; then
  show pacman -Q "${PACKAGES[@]}"
  show pacman -Qi caminito-git
  note "Expected (167, 170): Depends On has zenity and libcanberra."
  show ls /usr/share/mate-control-center/keybindings
  note "Expected: the three 50-caminito-*.xml, beside marco's own."
  result "caminito-git brings zenity and libcanberra"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
record_stage
;;

# ══ items ═════════════════════════════════════════════════════════════════
items)

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before the checks"
say "${#ITEMS[@]} checklist items are tagged $*. Each stage shows one, as the checklist has it."
in_caminito
show pacman -Q "${PACKAGES[@]}"
note "An item on the tty, nested or on a laptop says so in its steps: skip it with [s] and a"
note "note where this session can't run it, and run it where it says."
pause

# ── one for each item ─────────────────────────────────────────────────────
for title in "${ITEMS[@]}"; do
  checklist_stage "$title"
done

if [[ " $* " == *" M8 "* ]]; then
# ── 144 ───────────────────────────────────────────────────────────────────
stage "144: drag to unmaximise"
if ! done_already "Dragging a maximised or half-tiled window by its titlebar unmaximises it"; then
  say "144's Session check, which has no checklist item."
  step "Maximise a window, and drag it down by its titlebar, past the drag threshold."
  step "Tile a window to a half of the screen, and drag it by its titlebar the same way."
  note "Expected (144, 158): each unmaximises under the cursor, at the size it had before, and"
  note "goes on moving; no resize handle shows until it has."
  result "Dragging a maximised or half-tiled window by its titlebar unmaximises it"
fi

# ── the decisions ─────────────────────────────────────────────────────────
stage "The decisions left to confirm"
if ! done_already "The decisions M8's tickets left for the developer"; then
  say "M8's tickets took these, each for the developer to confirm, now that they've been seen:"
  grep -n -i -E 'for the developer to confirm|the developer.s to confirm' \
    "$HERE"/108-window-switcher.md "$HERE"/14[4-9]-*.md "$HERE"/1[5-6][0-9]-*.md "$HERE"/17[0-2]-*.md |
    sed -e "s|^$HERE/||" -e 's/^\([0-9]*\)-[^:]*:\([0-9]*\):- /\1, line \2: /' | cut -c1-400 | fold -s -w 96 | sed 's/^/    /' || true
  note "108, 151 and 160 are open on these alone: 108's are under its What was decided."
  note "In the note, name any you'd change; the rest stand."
  result "The decisions M8's tickets left for the developer"
fi

# ── the parity table ──────────────────────────────────────────────────────
checklist_stage "$PARITY"
fi

# ── last ──────────────────────────────────────────────────────────────────
record_stage
;;

# ══ x11 ═══════════════════════════════════════════════════════════════════
x11)

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "X11 MATE, with every Patched package installed"
if ! done_already "X11 MATE is unchanged with the Patched packages"; then
  say "Log out, log into MATE (the X11 session), and run this part there."
  show sh -c 'echo "XDG_SESSION_TYPE=$XDG_SESSION_TYPE MATE_WM_NAME=${MATE_WM_NAME-}"; pgrep -x marco >/dev/null && echo "marco runs"'
  show pacman -Q "${PACKAGES[@]}"
  item "$GATE"
  printf '\n'
  note "ADR 0011: a patch that turns on here, away from Caminito, is a bug. Also (167, 170):"
  note "Marco's own sounds and dialogs are as before, with libcanberra and zenity installed."
  result "X11 MATE is unchanged with the Patched packages"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "MATE on Wayfire, with every Patched package installed"
if ! done_already "MATE on Wayfire is unchanged with the Patched packages"; then
  say "Log out, log into MATE on Wayfire, run this part again there, and resume."
  show sh -c 'echo "XDG_SESSION_TYPE=$XDG_SESSION_TYPE MATE_WM_NAME=${MATE_WM_NAME-}"; pgrep -x wayfire >/dev/null && echo "wayfire runs"'
  note "The item's Wayfire steps are the ones shown in the stage before."
  result "MATE on Wayfire is unchanged with the Patched packages"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
record_stage
;;
esac
